140	// UnblockImpacts reports how many open candidates each named blocker alone
141	// prevents from becoming ready.
142	func (core *Core) UnblockImpacts(ctx context.Context, ids []model.ID) (map[model.ID]int, error) {
143		blockers, err := core.OpenBlockers(ctx)
144		if err != nil {
145			return nil, err
146		}
147		wanted := make(map[model.ID]struct{}, len(ids))
148		impact := make(map[model.ID]int, len(ids))
149		for _, id := range ids {
150			wanted[id], impact[id] = struct{}{}, 0
151		}
152		for _, open := range blockers {
153			if len(open) != 1 {
154				continue
155			}
156			if _, ok := wanted[open[0]]; ok {
157				impact[open[0]]++
158			}
159		}
160		return impact, nil
