247	func canonicalCycle(cycle []model.ID) []model.ID {
248		if len(cycle) == 0 {
249			return cycle
250		}
251		min := 0
252		for i := 1; i < len(cycle); i++ {
253			if cycle[i] < cycle[min] {
254				min = i
255			}
256		}
257		return append(append([]model.ID(nil), cycle[min:]...), cycle[:min]...)
258	}
